from rendu import Point

p = Point(6)
p.h('6.1 — Main et poignet : regarder, palper, mobiliser, documenter')
p.p('Inspecter les deux mains : couleur, peau, ongles, gonflement diffus ou localisé, nodules, axes et déformations. Une déformation ancienne ne renseigne pas à elle seule sur une souffrance vasculaire actuelle ; après traumatisme, compléter immédiatement par un examen neurovasculaire daté.', ['oa82-hug-inspection', 'pa82-radius-neurovasculaire'])
p.p('Palper la capsule et les interlignes à la recherche de synovite ou d’épanchement. L’interligne se déplace distalement lors de la flexion ; une pression palmaire régulière, notamment en flexion, déplace les tissus et le liquide dorsalement vers les doigts de l’examinateur. Décrire le site et la nature du gonflement avant de conclure à une arthrose.', 'oa82-hug-palpation')
p.p('Examiner flexion, extension, inclinaisons radiale et ulnaire du poignet ; la pronation et la supination impliquent aussi le coude. Pour les doigts, rechercher flexion, extension et rétraction, puis mesurer la distance pulpe-paume. L’amplitude et la préhension renseignent sur la fonction ; une faiblesse ne désigne pas automatiquement une lésion nerveuse.', ['oa82-hug-mobilite', 'oa82-hug-force'])
p.fenetre('Force : ce que cote l’échelle MRC', [
    ('MRC 0 : aucune contraction ; 1 : contraction visible ou palpable sans mouvement articulaire ; 2 : mouvement lorsque la pesanteur est éliminée ; 3 : mouvement contre la pesanteur ; 4 : mouvement contre résistance externe ; 5 : force normale contre forte résistance. Nommer le mouvement testé et comparer les côtés.', 'oa82-hug-force'),
    ('Pour les petites articulations de la main, la fonction de préhension est souvent plus pertinente que la seule cotation musculaire. Synovite, destruction articulaire, atteinte musculotendineuse, radiculopathie et neuropathie peuvent toutes entraîner une faiblesse.', 'oa82-hug-force')])
p.p('Une arthrose déformante associe une histoire de douleur à l’utilisation, un soulagement au repos et parfois une déformation en zigzag ; l’examen complet précède une imagerie ciblée. Une articulation chaude, rouge et douloureuse exige aussi de considérer une arthrite septique, avec ou sans fièvre.', ['p82-arthrose', 'p82-arthrose-diagnostic', 'pa82-arthrite-suspecte'])
p.fenetre('Deux gestes différents : extension distale et test de la table', [
    ('Doigt en maillet : demander une extension active de l’interphalangienne distale. L’impossibilité de la réaliser traduit la perte de continuité de l’appareil extenseur terminal ; examiner aussi peau et ongle pour identifier une lésion ouverte. Une lésion du lit unguéal peut signaler une fracture ouverte de Seymour.', ['pa82-maillet-actif', 'pa82-maillet-seymour']),
    ('Dupuytren : demander de poser la paume et les doigts à plat sur une table. L’impossibilité d’obtenir cet appui traduit une rétraction ; rechercher les nodules et cordes palmaires. Le mécanisme est une fibrose de l’aponévrose palmaire, distincte d’une rupture traumatique de l’extenseur terminal.', ['pa82-dupuytren-table', 'p82-dupuytren', 'pa82-maillet-actif'])])
p.h('6.2 — Après traumatisme du radius : la perfusion et les nerfs avant la seule mesure des angles')
p.p('Rechercher une ouverture cutanée, une menace sur la peau, une déformation et les signes de lésion associée. Tester l’extension du poignet pour le territoire radial, l’abduction des doigts pour l’ulnaire et le signe « OK » pour la composante motrice médiane décrite dans le support HUG. Rechercher les paresthésies pouvant accompagner un syndrome aigu du canal carpien.', 'p82-radius')
p.p('Documenter séparément sensibilité, motricité et pouls sur les deux membres, en nommant les nerfs testés ; répéter et horodater l’examen, notamment autour d’une réduction. Une mention globale « neurovasculaire normal » perd les éléments permettant de reconnaître une aggravation.', 'pa82-radius-neurovasculaire')
p.p('La sensibilité digitale se recherche sur chaque hémipulpe, yeux fermés, par contact léger, piqûre ou discrimination selon la méthode retenue. Un doigt dévascularisé peut être blanc et froid, sans recoloration ou avec une recoloration dépassant trois secondes ; l’absence de saignement actif ne rassure pas à elle seule, car un spasme peut masquer une lésion artérielle.', ['pa82-main-sensibilite', 'pa82-main-perfusion'])
p.p('Une absence de pouls, un saignement persistant ou un hématome expansif constituent des signes forts de lésion vasculaire. Une recoloration conservée ou un signal Doppler ne permettent pas de l’exclure. Si les signes forts persistent après réalignement ou réduction, l’exploration vasculaire doit être immédiate.', 'pa82-radius-ischemie')
p.h('6.3 — Pied : distinguer axe, souplesse et protection sensitive')
p.p('Pour l’hallux, observer la déviation latérale du gros orteil et la saillie médiale. Examiner la possibilité de ramener l’orteil vers la position neutre, la mobilité de la première métatarsophalangienne et la douleur lors de cette mobilisation : une articulation douloureuse et limitée conduit à rechercher une arthrose associée.', ['p82-hallux', 'pa82-hallux-examen'])
p.p('Chez l’enfant, comparer la voûte assis puis debout. Dans le pied plat souple, la voûte réapparaît hors charge et à la montée sur la pointe des pieds, avec redressement du talon. Une voûte qui ne se reconstitue pas et un talon restant dévié orientent vers un pied rigide, notamment une coalition, et changent l’indication d’exploration.', 'p82-plat-examen')
p.fenetre('Pied souple : deux manœuvres à décrire précisément', [
    ('Montée sur la pointe des pieds : observer la réapparition de la voûte et le redressement du talon. Le résultat attendu est une correction dynamique de l’aspect plat ; son absence fait rechercher une rigidité.', 'p82-plat-examen'),
    ('Test de Jack : mettre le gros orteil en dorsiflexion pour tendre l’aponévrose plantaire et observer la reconstitution de l’arche. Il s’agit d’un mécanisme de mise en tension plantaire, à distinguer de la seule observation de l’enfant assis.', 'p82-plat-examen'),
    ('Un pied souple indolore n’appelle pas d’imagerie systématique. Douleur, raideur, tension du mollet ou asymétrie justifient une évaluation ciblée ; la souplesse ne neutralise pas une fièvre ou une douleur nocturne.', ['pa82-plat-europe-imagerie', 'p82-plat-examen'])])
p.p('Chez une personne diabétique neuropathe avec peau intacte, rechercher un pied plus chaud, rouge et gonflé que le pied opposé. Mesurer la température infrarouge au point le plus chaud et au même site anatomique controlatéral ; la comparaison doit porter sur des sites correspondants. Aucun chiffre isolé de température ne définit à lui seul la rémission de Charcot.', ['pa82-charcot-r1', 'pa82-charcot-r3', 'p82-charcot'])
p.fenetre('Monofilament de 10 g : geste reproductible et interprétation', [
    ('Montrer d’abord la sensation sur la main, le coude ou le front. Le patient ne doit pas voir l’application. Examiner les trois sites plantaires de chaque pied représentés dans la figure IWGDF : pulpe de l’hallux, tête du premier métatarsien et tête du cinquième métatarsien.', ['pa82-monofilament-geste', 'p82-charcot-monofilament-sites-visuels']),
    ('Appliquer le filament perpendiculairement à la peau et appuyer jusqu’à sa courbure. L’approche, le contact et le retrait prennent environ deux secondes. Éviter ulcère, callosité, cicatrice et tissu nécrotique ; ne pas faire glisser le filament et ne pas multiplier des contacts rapides.', 'pa82-monofilament-geste'),
    ('Demander si le contact est perçu et où. Répéter deux fois en alternant avec une application fictive, soit trois questions par site. La sensibilité protectrice est présente avec deux réponses correctes sur trois et absente avec deux réponses incorrectes sur trois.', 'pa82-monofilament-interpretation'),
    ('Le dépistage du pied diabétique associe la sensibilité protectrice à l’interrogatoire sur la claudication et à la palpation des pouls pédieux. Le monofilament évalue la protection sensitive ; il ne remplace ni l’examen vasculaire ni l’exploration d’un pied chaud suspect de Charcot.', ['pa82-pied-depistage', 'pa82-charcot-r1'])])
p.h('6.4 — Genoux de l’enfant : standardiser la position avant de mesurer')
p.p('Examiner couché puis debout, genoux en extension maximale, rotules orientées vers l’avant. Une accentuation en charge peut traduire une composante capsuloligamentaire ; comparer des mesures réalisées dans des positions différentes risque donc de créer une fausse progression.', 'p82-genou-examen')
p.p('Pour un varum, rapprocher les malléoles et mesurer la distance intercondylienne ; pour un valgum, rapprocher les genoux et mesurer la distance intermalléolaire. Rechercher symétrie, progression et contexte osseux ou métabolique. Les repères d’orientation suisses tiennent compte de l’âge : un chiffre sans âge ni position ne suffit pas.', ['p82-genou-examen', 'pa82-genou-orientation'])
p.p('Un varum persistant après deux ans, un valgum avec distance intermalléolaire supérieure à six à huit centimètres après huit ans, une asymétrie ou une aggravation justifient une orientation selon la publication pédiatrique suisse. Ces critères orientent une évaluation ; ils ne désignent pas à eux seuls une cause précise ni une indication opératoire.', 'pa82-genou-orientation')
p.h('6.5 — Rachis : observer en position debout puis rechercher la rotation')
p.p('Debout, observer hauteur des épaules, omoplates, triangles de taille et bassin ; rechercher un déséquilibre du tronc. Examiner peau, croissance, mobilité rachidienne et neurologie, y compris réflexes abdominaux. Corriger une inégalité de longueur des membres avant d’attribuer toute obliquité pelvienne à une scoliose structurale.', 'p82-scoliose-clinique')
p.fenetre('Test d’Adams et scoliomètre', [
    ('Demander une flexion antérieure active du tronc, genoux tendus, mains jointes et bras relâchés ; l’examinateur observe par l’arrière. Rechercher une gibbosité thoracique ou une saillie lombaire, qui témoignent de la composante rotatoire.', ['p82-scoliose-clinique', 'p82-scoliose-hug']),
    ('Le scoliomètre mesure l’angle de rotation du tronc. Un angle d’environ cinq degrés ou davantage motive une investigation selon la source suisse ; ce n’est pas un angle de Cobb. Le Cobb se mesure sur une radiographie du rachis debout et sert à caractériser la courbure.', ['p82-scoliose-clinique', 'p82-scoliose-hug', 'p82-scoliose-radio']),
    ('Lorsque l’examen clinique et le scoliomètre sont normaux, le consensus SOSORT ne recommande pas une radiographie de référence systématique. L’exposition se justifie par une question clinique, et non par la seule disponibilité du cliché.', 'pa82-scoliose-normalite')])
p.p('Une déformation progressive des membres avec petite taille disproportionnée, retard de marche ou démarche dandinante fait examiner le contexte de rachitisme. Dans l’XLH, le tronc peut être relativement préservé tandis que les membres sont courts ; l’examen doit aussi rechercher les manifestations dentaires et les complications neurologiques rapportées.', 'p82-xlh-clinique')
p.sauver()
